#!/usr/bin/env node
/**
 * Patch the napi-rs generated WASI Node loader so absolute Windows host
 * paths work on Windows (see wasi-path-map.cjs for the rationale).
 *
 * The loader files are regenerated by `npx napi build --target
 * wasm32-wasip1-threads`, so this script must run again after every build
 * (the CI build-wasm job does this). It is idempotent: already-patched files
 * are left untouched.
 */

import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
// Both files are generated by `npm run build:wasi`, which names them through
// `napi build --js binding.wasi.cjs --dts binding.wasi.d.cts` so they cannot
// collide with the native build's `binding.*` output.
const loaderPath = join(root, 'binding.wasi.cjs')
const workerPath = join(root, 'wasi-worker.mjs')
const helperMarker = 'wasi-path-map.cjs'

const LOADER_ENV_INJECT = `
// Expose the host's real core count to the RAR5 encoder so the WASM build
// uses maximum parallelism by default. WASI reports only 1 core, so the Rust
// side would otherwise fall back to a small default pool. Honor an explicit
// override from the consumer if already set.
const __nodeOs = require('node:os')
if (!process.env.SA_RAR5_WASM_WORKERS) {
  try {
    const __cores = typeof __nodeOs.availableParallelism === 'function'
      ? __nodeOs.availableParallelism()
      : __nodeOs.cpus().length
    if (__cores > 0) process.env.SA_RAR5_WASM_WORKERS = String(__cores)
  } catch (_) { /* leave unset; Rust falls back to its default */ }
}
`

const LOADER_PREOPEN_OLD = `  preopens: {
    [__rootDir]: __rootDir,
  }`
const LOADER_PREOPEN_NEW = `  preopens: __wasiPathMap.wasiPreopens(__rootDir),`

const LOADER_EXPORTS_CREATE_NEW = `const __wasiCreateArchive = __napiModule.exports.createArchive
module.exports.createArchive = function __wasiCreateArchiveWrapper(
  opts,
  onProgress,
  signal,
) {
  return __wasiCreateArchive(
    __wasiPathMap.mapCreateArchiveOptions(opts),
    onProgress,
    signal,
  ).then((result) => __wasiPathMap.mapCreateResult(result))
}`
const LOADER_EXPORTS_APPEND_NEW = `const __wasiAppendEntries = __napiModule.exports.appendEntries
module.exports.appendEntries = function __wasiAppendEntriesWrapper(
  opts,
  onProgress,
  signal,
) {
  return __wasiAppendEntries(
    __wasiPathMap.mapAppendOptions(opts),
    onProgress,
    signal,
  ).then((result) => __wasiPathMap.mapCreateResult(result))
}`
const LOADER_EXPORTS_DELETE_NEW = `const __wasiDeleteEntries = __napiModule.exports.deleteEntries
module.exports.deleteEntries = function __wasiDeleteEntriesWrapper(
  archivePath,
  names,
  password,
  onProgress,
  signal,
) {
  return __wasiDeleteEntries(
    ...__wasiPathMap.mapDeleteArgs(
      archivePath,
      names,
      password,
      onProgress,
      signal,
    ),
  )
}`
const LOADER_EXPORTS_LIST_NEW = `const __wasiListEntries = __napiModule.exports.listEntries
module.exports.listEntries = function __wasiListEntriesWrapper(
  archivePath,
  password,
) {
  return __wasiListEntries(
    ...__wasiPathMap.mapListArgs(archivePath, password),
  )
}`
const LOADER_EXPORTS_REPAIR_NEW = `const __wasiRepairArchive = __napiModule.exports.repairArchive
module.exports.repairArchive = function __wasiRepairArchiveWrapper(
  inputPath,
  outputPath,
  onProgress,
  signal,
) {
  return __wasiRepairArchive(
    ...__wasiPathMap.mapRepairArgs(
      inputPath,
      outputPath,
      onProgress,
      signal,
    ),
  )
}`
const LOADER_EXPORTS_EXTRACT_NEW = `const __wasiExtractArchive = __napiModule.exports.extractArchive
module.exports.extractArchive = function __wasiExtractArchiveWrapper(
  archivePath,
  opts,
  signal,
) {
  return __wasiExtractArchive(
    ...__wasiPathMap.mapExtractArgs(archivePath, opts),
    signal,
  )
}`
const LOADER_EXPORTS_LIST_DETAILED_NEW = `const __wasiListEntriesDetailed = __napiModule.exports.listEntriesDetailed
module.exports.listEntriesDetailed = function __wasiListEntriesDetailedWrapper(
  archivePath,
  password,
) {
  return __wasiListEntriesDetailed(
    ...__wasiPathMap.mapListArgs(archivePath, password),
  )
}`
const LOADER_EXPORTS_LIST_QUICK_NEW = `const __wasiListEntriesQuick = __napiModule.exports.listEntriesQuick
module.exports.listEntriesQuick = function __wasiListEntriesQuickWrapper(
  archivePath,
  password,
) {
  return __wasiListEntriesQuick(
    ...__wasiPathMap.mapListArgs(archivePath, password),
  )
}`
const LOADER_EXPORTS_READ_MEMBER_NEW = `const __wasiReadMember = __napiModule.exports.readMember
module.exports.readMember = function __wasiReadMemberWrapper(
  archivePath,
  name,
  password,
) {
  return __wasiReadMember(
    __wasiPathMap.toGuestPath(archivePath),
    name,
    password,
  )
}`
const LOADER_EXPORTS_REBUILD_NEW = `const __wasiRebuildMissingVolumes = __napiModule.exports.rebuildMissingVolumes
module.exports.rebuildMissingVolumes = function __wasiRebuildMissingVolumesWrapper(
  firstVolume,
  onProgress,
  signal,
) {
  return __wasiRebuildMissingVolumes(
    __wasiPathMap.toGuestPath(firstVolume),
    onProgress,
    signal,
  ).then((paths) => __wasiPathMap.mapPathsToHost(paths))
}`
const LOADER_EXPORTS_TEST_ARCHIVE_NEW = `const __wasiTestArchive = __napiModule.exports.testArchive
module.exports.testArchive = function __wasiTestArchiveWrapper(
  archivePath,
  password,
) {
  return __wasiTestArchive(
    ...__wasiPathMap.mapListArgs(archivePath, password),
  )
}`
const LOADER_EXPORTS_EXTRACT_MEMBER_NEW = `const __wasiExtractMember = __napiModule.exports.extractMember
module.exports.extractMember = function __wasiExtractMemberWrapper(
  archivePath,
  name,
  destDir,
  password,
  signal,
) {
  return __wasiExtractMember(
    ...__wasiPathMap.mapExtractMemberArgs(
      archivePath,
      name,
      destDir,
      password,
      signal,
    ),
  ).then((path) => __wasiPathMap.toHostPath(path))
}`
const LOADER_EXPORTS_RENAME_NEW = `const __wasiRenameEntries = __napiModule.exports.renameEntries
module.exports.renameEntries = function __wasiRenameEntriesWrapper(
  archivePath,
  renames,
  password,
  signal,
) {
  return __wasiRenameEntries(
    ...__wasiPathMap.mapRenameArgs(
      archivePath,
      renames,
      password,
      signal,
    ),
  )
}`
const LOADER_EXPORTS_SET_COMMENT_NEW = `const __wasiSetComment = __napiModule.exports.setComment
module.exports.setComment = function __wasiSetCommentWrapper(
  archivePath,
  comment,
  password,
) {
  return __wasiSetComment(
    ...__wasiPathMap.mapCommentArgs(archivePath, comment, password),
  )
}`
// Same argument shape as `setComment` (archive path, text, password), so it
// shares the mapper. Missing here once shipped a WASI build whose
// `setMemberComment` handed a Windows host path straight to the sandbox and
// failed with ENOENT; `assertEveryExportIsWrapped` below now prevents a
// repeat.
const LOADER_EXPORTS_SET_MEMBER_COMMENT_NEW = `const __wasiSetMemberComment = __napiModule.exports.setMemberComment
module.exports.setMemberComment = function __wasiSetMemberCommentWrapper(
  archivePath,
  member,
  comment,
  password,
) {
  return __wasiSetMemberComment(
    ...__wasiPathMap.mapMemberCommentArgs(archivePath, member, comment, password),
  )
}`
const LOADER_EXPORTS_SET_RECOVERY_NEW = `const __wasiSetRecovery = __napiModule.exports.setRecovery
module.exports.setRecovery = function __wasiSetRecoveryWrapper(
  archivePath,
  percent,
  password,
) {
  return __wasiSetRecovery(
    ...__wasiPathMap.mapRecoveryArgs(archivePath, percent, password),
  )
}`
const LOADER_EXPORTS_LOCK_NEW = `const __wasiLockArchive = __napiModule.exports.lockArchive
module.exports.lockArchive = function __wasiLockArchiveWrapper(
  archivePath,
  password,
) {
  return __wasiLockArchive(
    ...__wasiPathMap.mapLockArgs(archivePath, password),
  )
}`

const WORKER_PREOPEN_OLD = `      preopens: {
        [__rootDir]: __rootDir,
      },`
const WORKER_PREOPEN_NEW = `      preopens: wasiPathMap.wasiPreopens(__rootDir),`

/**
 * Wrapper source per export, keyed by export name.
 *
 * Keyed rather than positional on purpose: the previous index-based table
 * silently omitted `setMemberComment`, so the WASI build handed a Windows
 * host path to the sandbox and failed with ENOENT. `assertEveryExportIsWrapped`
 * now compares this map against the generated loader and refuses to patch a
 * drift.
 */
const LOADER_WRAPPERS = {
  appendEntries: LOADER_EXPORTS_APPEND_NEW,
  createArchive: LOADER_EXPORTS_CREATE_NEW,
  deleteEntries: LOADER_EXPORTS_DELETE_NEW,
  extractArchive: LOADER_EXPORTS_EXTRACT_NEW,
  extractMember: LOADER_EXPORTS_EXTRACT_MEMBER_NEW,
  listEntries: LOADER_EXPORTS_LIST_NEW,
  listEntriesDetailed: LOADER_EXPORTS_LIST_DETAILED_NEW,
  listEntriesQuick: LOADER_EXPORTS_LIST_QUICK_NEW,
  lockArchive: LOADER_EXPORTS_LOCK_NEW,
  readMember: LOADER_EXPORTS_READ_MEMBER_NEW,
  rebuildMissingVolumes: LOADER_EXPORTS_REBUILD_NEW,
  renameEntries: LOADER_EXPORTS_RENAME_NEW,
  repairArchive: LOADER_EXPORTS_REPAIR_NEW,
  setComment: LOADER_EXPORTS_SET_COMMENT_NEW,
  setMemberComment: LOADER_EXPORTS_SET_MEMBER_COMMENT_NEW,
  setRecovery: LOADER_EXPORTS_SET_RECOVERY_NEW,
  testArchive: LOADER_EXPORTS_TEST_ARCHIVE_NEW,
}

const EXPORT_LINE_PATTERN = /^module\.exports\.(\w+) = __napiModule\.exports\.\1$/gm

/** Every export the generated loader re-exports from the addon. */
function generatedExports(source) {
  const names = new Set()
  for (const match of source.matchAll(EXPORT_LINE_PATTERN)) {
    names.add(match[1])
  }
  return names
}

/**
 * Fail when the loader and the wrapper table disagree.
 *
 * A missing wrapper is the ENOENT bug above; a stale wrapper is dead code.
 * Both are silent at runtime, so the build must reject them. Exported so the
 * WASI test suite can exercise the guard directly.
 */
export function assertEveryExportIsWrapped(source) {
  const generated = generatedExports(source)
  const unwrapped = [...generated].filter((name) => !(name in LOADER_WRAPPERS))
  const stale = Object.keys(LOADER_WRAPPERS).filter((name) => !generated.has(name))
  if (unwrapped.length > 0) {
    throw new Error(
      `WASI loader exports ${unwrapped.join(', ')} but patch-wasi-loader.mjs ` +
        'has no wrapper for them; add one so their paths are translated',
    )
  }
  if (stale.length > 0) {
    throw new Error(
      `patch-wasi-loader.mjs wraps ${stale.join(', ')} but the WASI loader no ` +
        'longer exports them; drop the stale wrapper',
    )
  }
  return generated
}

function patchLoader(source) {
  if (source.includes(helperMarker)) return source
  const requireInsert = `const { createContext: __emnapiCreateContext } = require('@emnapi/runtime')`
  if (!source.includes(requireInsert)) {
    throw new Error(
      'loader template changed: expected @emnapi/runtime require line',
    )
  }
  const exports = assertEveryExportIsWrapped(source)
  source = source.replace(
    requireInsert,
    `${requireInsert}\nconst __wasiPathMap = require('./wasi-path-map.cjs')` +
      LOADER_ENV_INJECT,
  )
  if (!source.includes(LOADER_PREOPEN_OLD)) {
    throw new Error('loader template changed: expected default preopens block')
  }
  source = source.replace(LOADER_PREOPEN_OLD, LOADER_PREOPEN_NEW)
  for (const name of exports) {
    source = source.replace(
      `module.exports.${name} = __napiModule.exports.${name}`,
      LOADER_WRAPPERS[name],
    )
  }
  return source
}

function patchWorker(source) {
  if (source.includes(helperMarker)) return source
  const importInsert = `import { parentPort, Worker } from "node:worker_threads";`
  if (!source.includes(importInsert)) {
    throw new Error(
      'worker template changed: expected node:worker_threads import line',
    )
  }
  source = source.replace(
    importInsert,
    `${importInsert}\nimport wasiPathMap from './wasi-path-map.cjs';`,
  )
  if (!source.includes(WORKER_PREOPEN_OLD)) {
    throw new Error('worker template changed: expected default preopens block')
  }
  source = source.replace(WORKER_PREOPEN_OLD, WORKER_PREOPEN_NEW)
  return source
}

// Only patch when run as a script: the test suite imports this module for
// `assertEveryExportIsWrapped` and must not need a built WASI loader.
if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const loader = readFileSync(loaderPath, 'utf8')
  writeFileSync(loaderPath, patchLoader(loader))

  const worker = readFileSync(workerPath, 'utf8')
  writeFileSync(workerPath, patchWorker(worker))

  console.log(`patched ${loaderPath} and ${workerPath}`)
}
